// Кейс: .qa/tests/history/HIST-007.md · план: .qa/e2e-app/specs/app.md (1.29)
// Мониторинг ~60 с → приложение закрыто (terminateApp) → N минут → открыто (activateApp) → «היסטוריה» → верхний сеанс:
// длительность и конец — по последнему сигналу (≈ закрытие), а не по времени повторного открытия (баг: «17:13 שעות ניטור»).
// ЗАПУСКАЕТ МОНИТОРИНГ (сеанс в «היסטוריה») — только с BANCI_MONITORING=1.
// Часы телефона и компьютера должны совпадать (автоматическое время), допуск 2 мин. Переход через полночь не поддерживается.
import { by, assert, APP_BUNDLE_ID } from '../../lib/appium.mjs';
import { requireMonitoringOptIn, startMonitoring, timerSeconds, waitTimer } from '../../lib/monitoring.mjs';
import { onHome, openTab } from '../../lib/banci.mjs';

export const name = 'Прерванный мониторинг (приложение закрыто N мин) → «היסטוריה»: «N דק׳ ניטור» и «הניטור הופסק כי האפליקציה נסגרה» по времени закрытия, не открытия #af53b1 @iphone @app @data';

const RUN_SEC = 60;
const SLACK_MIN = 2;
const STOPPED = 'הניטור הופסק כי האפליקציה נסגרה';
/** Строка сеанса в истории: «N דק׳ ניטור» / «… שעות ניטור» (как в 1.5). */
const ROW = '(name CONTAINS "ניטור" OR label CONTAINS "ניטור") AND (name CONTAINS "דק" OR label CONTAINS "דק" OR name CONTAINS "שע" OR label CONTAINS "שע") AND NOT (name CONTAINS "ניטורים" OR label CONTAINS "ניטורים")';
const RANGE_RE = /(\d{1,2}):(\d{2})\s*[–—-]\s*(\d{1,2}):(\d{2})/;
const RANGE = 'name MATCHES ".*[0-9]{1,2}:[0-9]{2} ?[–—-] ?[0-9]{1,2}:[0-9]{2}.*" OR label MATCHES ".*[0-9]{1,2}:[0-9]{2} ?[–—-] ?[0-9]{1,2}:[0-9]{2}.*"';
const CLOCK = 'type == "XCUIElementTypeStaticText" AND label MATCHES "^[0-9]{1,2}:[0-9]{2}$"';

const hhmm = (d) => d.toTimeString().slice(0, 5);
/** Минуты от полуночи по локальному времени компьютера. */
const dayMin = (d) => d.getHours() * 60 + d.getMinutes() + d.getSeconds() / 60;
const text = async (el) => `${(await el.attr('label')) ?? ''} ${(await el.attr('name')) ?? ''}`;

/** «N דק׳» / «H:MM שעות» / «שעה» / «N שעות» → минуты. */
function durationMin(t) {
  const mins = +(t.match(/(\d+)\s*דק/)?.[1] ?? 0);
  let m = t.match(/(\d+):(\d{2})\s*שע/);
  if (m) return +m[1] * 60 + +m[2];
  m = t.match(/(\d+)\s*שע/);
  if (m) return +m[1] * 60 + mins;
  if (/שעה/.test(t)) return 60 + mins;
  if (/\d+\s*דק/.test(t)) return mins;
  if (/דקה/.test(t)) return 1;
  return null;
}

async function topmost(els) {
  const rects = await Promise.all(els.map((e) => e.rect()));
  let best = 0;
  rects.forEach((r, i) => { if (r.y < rects[best].y) best = i; });
  return els[best];
}

/** Время события «HH:MM»: из его подписи или ближайший по высоте StaticText «HH:MM». */
async function eventClock(app, el) {
  const own = (await text(el)).match(/(\d{1,2}):(\d{2})/);
  if (own) return +own[1] * 60 + +own[2];
  const r = await el.rect();
  const cy = r.y + r.height / 2;
  let best = null, bestD = Infinity;
  for (const c of await app.findAll(CLOCK)) {
    const cr = await c.rect();
    const d = Math.abs(cr.y + cr.height / 2 - cy);
    if (d < bestD) { bestD = d; best = c; }
  }
  assert(best && bestD < 60, `у события «${STOPPED}» видно время «HH:MM»`);
  const [h, m] = String(await best.attr('label')).split(':').map(Number);
  return h * 60 + m;
}

export default async function (app) {
  requireMonitoringOptIn();
  const waitMin = Number(process.env.BANCI_INTERRUPT_WAIT_MIN ?? 4);
  assert(Number.isFinite(waitMin) && waitMin >= 3, `BANCI_INTERRUPT_WAIT_MIN ≥ 3 (сейчас ${process.env.BANCI_INTERRUPT_WAIT_MIN}) — иначе «время до закрытия + 2 мин» и «время до открытия» не различить`);

  // 1. Мониторинг ~60 с. Старт = сейчас − показание таймера.
  await startMonitoring(app);
  const t0 = await timerSeconds(app);
  const startAt = new Date(Date.now() - t0 * 1000);
  const tKill = await waitTimer(app, RUN_SEC);
  await app.screenshot('af53b1-auto-before-kill').catch(() => {});

  // 2. Закрыть приложение полностью (как смахнуть из переключателя).
  await app.exec('mobile: terminateApp', { bundleId: APP_BUNDLE_ID });
  const killAt = new Date();
  console.log(`     [#af53b1] старт ${hhmm(startAt)}, закрыто ${killAt.toTimeString().slice(0, 8)} (таймер ${tKill} с), ждём ${waitMin} мин`);

  // 3. N минут приложение закрыто — это сам сценарий тикета (интервал разрыва), не ожидание результата.
  await new Promise((r) => setTimeout(r, waitMin * 60000));

  // 4. Открыть приложение.
  await app.activate();
  const reopenAt = new Date();
  console.log(`     [#af53b1] открыто ${reopenAt.toTimeString().slice(0, 8)}`);
  await onHome(app);

  const toKillMin = (killAt - startAt) / 60000;     // ~1 мин
  const toReopenMin = (reopenAt - startAt) / 60000; // ~1 + N мин
  const maxEnd = dayMin(killAt) + SLACK_MIN;

  // 5. «היסטוריה» → верхний сеанс: длительность в минутах.
  await openTab(app, 'היסטוריה');
  await app.waitFor(ROW, { timeout: 20000, what: 'строка сеанса «N דק׳ ניטור» в «היסטוריה»' });
  const row = await topmost(await app.findAll(ROW));
  const rowText = (await text(row)).trim();
  const dur = durationMin(rowText);
  assert(dur !== null, `в строке истории читается длительность («${rowText}»)`);
  assert(dur <= Math.ceil(toKillMin) + SLACK_MIN, `длительность ${dur} мин ≤ время до закрытия (${toKillMin.toFixed(1)} мин) + ${SLACK_MIN} мин («${rowText}»)`);
  assert(dur < Math.floor(toReopenMin), `длительность ${dur} мин меньше времени до повторного открытия (${toReopenMin.toFixed(1)} мин) — конец не по открытию («${rowText}»)`);
  await app.screenshot('af53b1-auto-history-row').catch(() => {});
  await row.click();

  // 6. Детали: «מה קרה», диапазон «HH:MM–HH:MM».
  await app.waitFor(by.exact('מה קרה'), { timeout: 15000, what: 'блок «מה קרה» в деталях сеанса' });
  const rangeEls = await app.findAll(RANGE);
  if (rangeEls.length) {
    const m = (await text(rangeEls[0])).match(RANGE_RE);
    if (m) {
      const s = +m[1] * 60 + +m[2], e = +m[3] * 60 + +m[4];
      assert(Math.abs(s - Math.floor(dayMin(startAt))) <= 1, `начало ${m[1]}:${m[2]} = старт ${hhmm(startAt)} (±1 мин) — это новый сеанс`);
      assert(e <= maxEnd, `конец ${m[3]}:${m[4]} ≤ закрытие ${hhmm(killAt)} + ${SLACK_MIN} мин (не время открытия ${hhmm(reopenAt)})`);
    }
  } else {
    console.log('     [#af53b1] диапазон «HH:MM–HH:MM» в деталях не найден Appium — проверка начала/конца по событию ниже');
  }

  // 7. «מה קרה»: событие «הניטור הופסק כי האפליקציה נסגרה» со временем ≤ закрытие + 2 мин.
  const ev = await app.scrollTo(by.contains(STOPPED), { max: 6, what: `событие «${STOPPED}» в «מה קרה»` });
  const evMin = await eventClock(app, ev);
  const evHHMM = `${String(Math.floor(evMin / 60)).padStart(2, '0')}:${String(evMin % 60).padStart(2, '0')}`;
  assert(evMin >= Math.floor(dayMin(startAt)), `время события ${evHHMM} не раньше старта ${hhmm(startAt)}`);
  assert(evMin <= maxEnd, `«${STOPPED}» в ${evHHMM} ≤ закрытие ${hhmm(killAt)} + ${SLACK_MIN} мин (не время открытия ${hhmm(reopenAt)})`);
  await app.screenshot('af53b1-auto-detail').catch(() => {});
}
